import java.nio.file.*;
import java.util.*;

/** Real CEF same-language dependency download/start/call/stop-order flow; no Provider or OS input. */
@EventBusSubscriber(modid="mineagent_runtime",value=Dist.CLIENT)
public final class ClientDependencySmokeClient {
    private static final Gson JSON=new Gson();private static JsonObject probe;private static int ticks,phase;private static boolean backup,trusted,trustPressed,opened,finished;
    private ClientDependencySmokeClient(){}public static void accept(JsonObject value){if(ClientDependencySmokeServer.enabled())probe=value;}private static Path root(){return Minecraft.getInstance().gameDirectory.toPath().resolve("client-dependency-smoke");}private static void write(String name,Object value)throws Exception{Files.createDirectories(root());Files.writeString(root().resolve(name+".json"),JSON.toJson(value));}private static void require(boolean value,String code){if(!value)throw new IllegalStateException(code);}private static void script(String code){var host=WebGuiHostAdapter.INSTANCE;host.browser().executeJavaScript("(()=>{"+code+"})();",host.browser().getURL(),0);}private static void action(String key,String code){script("window.__clientDependencySmoke??={};if(window.__clientDependencySmoke["+JSON.toJson(key)+"])return;const ok=(()=>{"+code+"})();if(ok)window.__clientDependencySmoke["+JSON.toJson(key)+"]=true;");}private static void poll()throws Exception{script("window.dispatchEvent(new Event('mineagent:client-script-probe'));");if(ticks%40==0){var status=new LinkedHashMap<String,Object>();for(String name:ClientDependencySmokeServer.NAMES)try{var a=asset(name);status.put(name,Map.of("state",a.state(),"status",ClientScriptPackages.runtimeStatus(a.filename()),"loaded",ClientScriptPackages.loaded(a.filename())));}catch(Exception missing){status.put(name,"MISSING");}write("progress",Map.of("phase",phase,"ticks",ticks,"status",status,"view",ClientScriptPackages.read(0),"probe",probe==null?"{}":probe.toString()));}}private static String text(String key){return probe==null||!probe.has(key)?"":probe.get(key).getAsString();}
    private static LocalClientScriptStore.Asset asset(String name)throws Exception{var id=ClientDependencySmokeServer.PACKAGES.get(name).packageId();return LocalClientScriptStore.get(Minecraft.getInstance().gameDirectory.toPath()).list().stream().filter(a->a.manifest().packageId().equals(id)).findFirst().orElseThrow(()->new IllegalStateException("CLIENT_DEPENDENCY_ASSET_MISSING:"+name));}
    private static boolean java(int index){return index>=2&&index!=5;}private static String expected(int index){return switch(index){case 0->"RHINO_DEP_READY";case 1->"RHINO_CONSUMER:RHINO_DEP:OK";case 2->"JAVA_BASE_READY";case 3->"JAVA_MID:JAVA_BASE";case 4->"JAVA_CONSUMER:JAVA_MID:JAVA_BASE";case 5->"RHINO_TO_JAVA:JAVA_BASE:RHINO";default->"JAVA_TO_RHINO:RHINO_DEP:JAVA";};}private static String cleaned(int index){return switch(index){case 0->"RHINO_DEP_CLEANED";case 1->"RHINO_CONSUMER_CLEANED";case 2->"JAVA_BASE_CLEANED";case 3->"JAVA_MID_CLEANED";case 4->"JAVA_CONSUMER_CLEANED";case 5->"RHINO_TO_JAVA_CLEANED";default->"JAVA_TO_RHINO_CLEANED";};}
    private static void fail(Throwable error)throws Exception{finished=true;write("client-failure",Map.of("phase",phase,"ticks",ticks,"error",error.toString(),"serverFailure",Objects.toString(ClientDependencySmokeServer.failure,""),"probe",probe==null?"{}":probe.toString()));WebGuiHostAdapter.INSTANCE.close();Minecraft.getInstance().stop();}
    @SuppressWarnings("unchecked") private static Map<String,Object> item(String name)throws Exception{return ((List<Map<String,Object>>)ClientScriptPackages.read(0).get("items")).stream().filter(v->v.get("name").equals(name)).findFirst().orElseThrow();}
    private static void blocked(String name)throws Exception{var a=asset(name);String env=String.valueOf(ClientScriptPackages.read(0).get("environment"));try{ClientScriptPackages.change(UUID.randomUUID(),a.filename(),"STOP",a.revision(),env,true,"SMOKE",()->true);throw new IllegalStateException("CLIENT_DEPENDENCY_STOP_NOT_BLOCKED");}catch(IllegalStateException expected){require(ClientScriptPackages.code(expected).equals("CLIENT_CODE_DEPENDENCY_IN_USE"),"CLIENT_DEPENDENCY_STOP_CODE");}}
    @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception{if(!ClientDependencySmokeServer.enabled()||finished)return;var mc=Minecraft.getInstance();var host=WebGuiHostAdapter.INSTANCE;ticks++;try{if(ticks>16000)throw new IllegalStateException("CLIENT_DEPENDENCY_CEF_TIMEOUT_"+phase);if(ClientDependencySmokeServer.failure!=null)throw new IllegalStateException(ClientDependencySmokeServer.failure);if(!backup&&mc.screen instanceof net.minecraft.client.gui.screens.BackupConfirmScreen screen){backup=true;var field=screen.getClass().getDeclaredField("onProceed");field.setAccessible(true);((net.minecraft.client.gui.screens.BackupConfirmScreen.Listener)field.get(screen)).proceed(false,false);}if(!trusted&&mc.player!=null){if(ticks%20==0)net.neoforged.neoforge.client.network.ClientPacketDistributor.sendToServer(new dev.mineagent.runtime.neoforge.network.MineAgentPayloads.PanelRequest());if(mc.screen instanceof dev.mineagent.runtime.neoforge.client.screen.ControlCenterScreen screen&&!trustPressed)for(var child:screen.children())if(child instanceof net.minecraft.client.gui.components.Button button&&button.active&&button.getMessage().getString().equals("信任此服务器")){button.onPress(new net.minecraft.client.input.InputWithModifiers(){public int input(){return org.lwjgl.glfw.GLFW.GLFW_KEY_ENTER;}public int modifiers(){return 0;}});trustPressed=true;net.neoforged.neoforge.client.network.ClientPacketDistributor.sendToServer(new dev.mineagent.runtime.neoforge.network.MineAgentPayloads.PanelRequest());break;}var snapshot=dev.mineagent.runtime.neoforge.network.PanelSnapshotInbox.snapshot();String fingerprint=snapshot.values().getOrDefault("security.identityFingerprint","");if(trustPressed&&new dev.mineagent.runtime.client.trust.ServerTrustStore(mc.gameDirectory.toPath().resolve("config/mineagent-trusted-servers.properties")).status("local-integrated",fingerprint)==dev.mineagent.runtime.client.trust.TrustStatus.TRUSTED){trusted=true;write("trust",Map.of("actualNativeTrustButton",true,"fingerprint",fingerprint,"systemInputInjected",false));mc.setScreen(null);}else return;}if(ClientDependencySmokeServer.PACKAGES.size()!=7)return;if(!opened){opened=true;host.open();}if(!host.ready()||UiClientSessions.current()==null||ticks%10!=0)return;poll();String catalog=text("catalogText"),manager=text("clientScriptText");if(phase==0){action("catalog","document.querySelector('#open-package-catalog')?.click();return true;");if(ClientDependencySmokeServer.NAMES.stream().allMatch(catalog::contains))phase=1;return;}if(phase>=1&&phase<=14){int index=(phase-1)/2;String name=ClientDependencySmokeServer.NAMES.get(index);if((phase&1)==1){action("open-"+index,"const p=[...document.querySelectorAll('.window')].find(n=>n.dataset.viewId==='runtime-package-catalog');const c=[...p?.querySelectorAll('article')||[]].find(n=>n.querySelector('strong')?.textContent==="+JSON.toJson(name)+");const b=[...c?.querySelectorAll('button')||[]].find(n=>n.textContent==='本机 CLIENT 原生代码下载 / 执行');if(!b)return false;b.click();return true;");if(manager.contains("所选服务器包："+name))phase++;}else{String label=java(index)?"下载 CLIENT Java 源码（不编译/执行）":"下载 CLIENT Rhino（不执行）";action("download-"+index,"const p=[...document.querySelectorAll('.window')].find(n=>n.dataset.viewId==='runtime-client-scripts');const b=[...p?.querySelectorAll('button')||[]].find(n=>n.textContent==="+JSON.toJson(label)+");if(!b||b.disabled)return false;b.click();return true;");try{var a=asset(name);if(a.state().equals("DOWNLOADED")&&!a.localConsent()){write("download-"+index,Map.of("name",name,"asset",a));phase++;}}catch(IllegalStateException waiting){}}return;}if(phase==15){action("local-manager","document.querySelector('#open-client-scripts')?.click();return true;");if(ClientDependencySmokeServer.NAMES.stream().allMatch(manager::contains))phase=16;return;}if(phase>=16&&phase<=22){int index=phase-16;String name=ClientDependencySmokeServer.NAMES.get(index),language=java(index)?"JAVA":"RHINO";action("start-"+index,"const p=[...document.querySelectorAll('.window')].find(n=>n.dataset.viewId==='runtime-client-scripts');const c=[...p?.querySelectorAll('article')||[]].find(n=>n.querySelector('strong')?.textContent.startsWith("+JSON.toJson(name)+"));const q=c?.querySelector('input[type=checkbox]');const b=[...c?.querySelectorAll('button')||[]].find(n=>n.textContent==='本机编译并启动 CLIENT "+language+"');if(!q||!b||b.disabled)return false;q.checked=true;b.click();return true;");var a=asset(name);if(a.state().equals("RUNNING")&&ClientScriptPackages.loaded(a.filename())&&ClientScriptPackages.runtimeStatus(a.filename()).equals(expected(index)))phase++;return;}if(phase==23){blocked(ClientDependencySmokeServer.NAMES.get(0));blocked(ClientDependencySmokeServer.NAMES.get(2));blocked(ClientDependencySmokeServer.NAMES.get(3));var states=new LinkedHashMap<String,Object>();for(String name:ClientDependencySmokeServer.NAMES)states.put(name,item(name));write("running",states);phase=24;return;}if(phase>=24&&phase<=30){int index=30-phase;String name=ClientDependencySmokeServer.NAMES.get(index);action("stop-"+index,"const p=[...document.querySelectorAll('.window')].find(n=>n.dataset.viewId==='runtime-client-scripts');const c=[...p?.querySelectorAll('article')||[]].find(n=>n.querySelector('strong')?.textContent.startsWith("+JSON.toJson(name)+"));const q=c?.querySelector('input[type=checkbox]');const b=[...c?.querySelectorAll('button')||[]].find(n=>n.textContent==='停止此本机代码');if(!q||!b||b.disabled)return false;q.checked=true;b.click();return true;");var a=asset(name);if(a.state().equals("STOPPED")&&!ClientScriptPackages.loaded(a.filename())&&ClientScriptPackages.runtimeStatus(a.filename()).equals(cleaned(index)))phase++;return;}if(phase==31){var result=new LinkedHashMap<String,Object>();for(int i=0;i<7;i++){String name=ClientDependencySmokeServer.NAMES.get(i);result.put(name,Map.of("asset",asset(name),"status",ClientScriptPackages.runtimeStatus(asset(name).filename()),"build",ClientScriptPackages.build(asset(name).filename())));}write("result",Map.of("status","REAL_CEF_CLIENT_RHINO_JAVA_MIXED_DEPENDENCY_GRAPH_VERIFIED","packages",result,"stopOrderProtected",true,"rhinoCall","RHINO_CONSUMER:RHINO_DEP:OK","javaTransitiveCall","JAVA_CONSUMER:JAVA_MID:JAVA_BASE","rhinoToJavaCall","RHINO_TO_JAVA:JAVA_BASE:RHINO","javaToRhinoCall","JAVA_TO_RHINO:RHINO_DEP:JAVA","providerCalls",0,"systemInputInjected",false,"fullV1",false));finished=true;dev.mineagent.runtime.neoforge.MineAgentRuntimeMod.LOGGER.info("MINEAGENT_CLIENT_DEPENDENCY_OK");host.close();mc.stop();}}
        catch(Exception error){fail(error);throw error;}}
}
